// Smash Arena - authoritative game server.
// Serves the client from /public and runs the battle simulation at 60Hz,
// broadcasting snapshots at 30Hz. Phases: lobby -> charselect -> mapselect -> battle -> victory -> charselect...

const http = require('http');
const fs = require('fs');
const path = require('path');
const os = require('os');
const { WebSocketServer } = require('ws');
const { PHYS, CHARACTERS, MAPS } = require('./public/shared.js');

const PORT = process.env.PORT || 3000;
const PUBLIC_DIR = path.join(__dirname, 'public');
const MIME = {
  '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css',
  '.png': 'image/png', '.ico': 'image/x-icon', '.svg': 'image/svg+xml'
};

const server = http.createServer((req, res) => {
  let urlPath = decodeURIComponent(req.url.split('?')[0]);
  if (urlPath === '/') urlPath = '/index.html';
  const filePath = path.join(PUBLIC_DIR, path.normalize(urlPath));
  if (!filePath.startsWith(PUBLIC_DIR)) { res.writeHead(403); return res.end(); }
  fs.readFile(filePath, (err, data) => {
    if (err) { res.writeHead(404); return res.end('Not found'); }
    res.writeHead(200, { 'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream' });
    res.end(data);
  });
});

const wss = new WebSocketServer({ server });

// ---------------------------------------------------------------------------
// Game state
// ---------------------------------------------------------------------------

const game = {
  phase: 'lobby',            // lobby | charselect | mapselect | battle | victory
  players: new Map(),        // id -> player
  map: null,                 // map key during battle
  countdownEnd: 0,           // battle freeze until this time
  victoryAt: 0,              // when victory screen started
  winnerId: null,
  tick: 0
};
let nextId = 1;

function now() { return Date.now() / 1000; }

function broadcast(msg) {
  const str = JSON.stringify(msg);
  for (const p of game.players.values()) {
    if (p.ws.readyState === 1) p.ws.send(str);
  }
}

function participants() {
  return [...game.players.values()].filter(p => !p.spectating);
}

function lobbyState() {
  return {
    type: 'state',
    phase: game.phase,
    map: game.map,
    winnerId: game.winnerId,
    players: [...game.players.values()].map(p => ({
      id: p.id, name: p.name, host: p.host, ready: p.ready,
      char: p.char, vote: p.vote, spectating: p.spectating
    }))
  };
}

function syncState() { broadcast(lobbyState()); }

function promoteHost() {
  if (![...game.players.values()].some(p => p.host)) {
    const first = game.players.values().next().value;
    if (first) first.host = true;
  }
}

// ---------------------------------------------------------------------------
// Phase transitions
// ---------------------------------------------------------------------------

function toCharSelect() {
  game.phase = 'charselect';
  game.winnerId = null;
  for (const p of game.players.values()) {
    p.ready = false;
    p.vote = null;
    p.spectating = false;   // everyone waiting joins the next round
  }
  syncState();
}

function toMapSelect() {
  game.phase = 'mapselect';
  for (const p of game.players.values()) p.vote = null;
  syncState();
}

function pickMap() {
  const votes = {};
  for (const p of participants()) {
    if (p.vote && MAPS[p.vote]) votes[p.vote] = (votes[p.vote] || 0) + 1;
  }
  const keys = Object.keys(votes);
  if (keys.length === 0) return Object.keys(MAPS)[Math.floor(Math.random() * 3)];
  const max = Math.max(...keys.map(k => votes[k]));
  const top = keys.filter(k => votes[k] === max);
  return top[Math.floor(Math.random() * top.length)];
}

function toBattle() {
  game.phase = 'battle';
  game.map = pickMap();
  game.countdownEnd = now() + 3;
  const map = MAPS[game.map];
  const parts = participants();
  parts.forEach((p, i) => {
    const [sx, sy] = map.spawns[i % map.spawns.length];
    Object.assign(p, {
      x: sx, y: sy, vx: 0, vy: 0,
      face: sx < 0 ? 1 : -1,
      grounded: false, jumpsLeft: 0, droppedThrough: false,
      dmg: 0, stocks: PHYS.STOCKS,
      alive: true, deadT: 0, invulnT: 0, hitstunT: 0,
      attack: null, anim: 'idle', animT: 0,
      input: { left: 0, right: 0, up: 0, down: 0, jump: 0, jab: 0, smash: 0 },
      prevJump: 0, prevJab: 0, prevSmash: 0, prevDown: 0
    });
  });
  syncState();
  broadcast({ type: 'battleStart', map: game.map, countdownEnd: game.countdownEnd });
}

function toVictory(winner) {
  game.phase = 'victory';
  game.winnerId = winner ? winner.id : null;
  game.victoryAt = now();
  syncState();
}

function checkBattleEnd() {
  const parts = participants();
  const alive = parts.filter(p => p.alive);
  if (parts.length > 1 && alive.length <= 1) toVictory(alive[0] || null);
  else if (parts.length === 1 && alive.length === 0) toVictory(null);
  else if (parts.length === 0) toCharSelect();
}

// ---------------------------------------------------------------------------
// Battle simulation
// ---------------------------------------------------------------------------

function respawn(p, map) {
  p.x = 0; p.y = -380;
  p.vx = 0; p.vy = 0;
  p.dmg = 0;
  p.hitstunT = 0; p.attack = null;
  p.invulnT = PHYS.RESPAWN_INVULN;
  p.grounded = false; p.jumpsLeft = 1;
  p.anim = 'fall'; p.animT = 0;
}

function koPlayer(p, map) {
  p.stocks--;
  const side = p.x < map.blast.left ? -1 : p.x > map.blast.right ? 1 : 0;
  broadcast({ type: 'event', kind: 'ko', id: p.id, x: Math.round(p.x), y: Math.round(p.y), side });
  p.attack = null; p.hitstunT = 0;
  if (p.stocks > 0) {
    p.deadT = PHYS.RESPAWN_DELAY;
  } else {
    p.alive = false;
    broadcast({ type: 'event', kind: 'eliminated', id: p.id });
  }
  checkBattleEnd();
}

function tryHit(attacker, atk, others) {
  const cx = attacker.x + attacker.face * (24 + atk.range / 2);
  const cy = attacker.y - 56;
  const hw = atk.range / 2, hh = atk.height / 2;
  for (const v of others) {
    if (v === attacker || !v.alive || v.deadT > 0 || v.invulnT > 0) continue;
    if (attacker.attack.hitSet.has(v.id)) continue;
    const vx0 = v.x - PHYS.BODY_W / 2, vx1 = v.x + PHYS.BODY_W / 2;
    const vy0 = v.y - PHYS.BODY_H, vy1 = v.y;
    if (cx + hw < vx0 || cx - hw > vx1 || cy + hh < vy0 || cy - hh > vy1) continue;

    attacker.attack.hitSet.add(v.id);
    const chr = CHARACTERS[v.char] || CHARACTERS.blaze;
    v.dmg = Math.min(999, v.dmg + atk.dmg);
    const kb = (atk.baseKb + v.dmg * atk.kbScale) / chr.weight;
    v.vx = Math.cos(atk.angle) * kb * attacker.face;
    v.vy = -Math.sin(atk.angle) * kb;
    if (v.grounded && v.vy > -160) v.vy = -160;
    v.grounded = false;
    v.hitstunT = Math.min(0.9, Math.max(0.14, kb / 1500));
    v.attack = null;
    v.anim = 'hit'; v.animT = 0;
    broadcast({
      type: 'event', kind: 'hit', id: v.id, by: attacker.id,
      x: Math.round(v.x), y: Math.round(v.y - 56),
      dmg: atk.dmg, heavy: atk.dmg >= 11 ? 1 : 0, face: attacker.face
    });
  }
}

function simPlayer(p, dt, map, others) {
  const chr = CHARACTERS[p.char] || CHARACTERS.blaze;
  const inp = p.input;

  if (!p.alive) return;
  if (p.deadT > 0) {
    p.deadT -= dt;
    if (p.deadT <= 0) respawn(p, map);
    return;
  }
  if (p.invulnT > 0) p.invulnT -= dt;

  const inHitstun = p.hitstunT > 0;
  if (inHitstun) p.hitstunT -= dt;

  // --- Attack state machine ---
  if (p.attack) {
    p.attack.t += dt;
    const atk = chr.attacks[p.attack.key];
    if (p.attack.t >= atk.startup && p.attack.t < atk.startup + atk.active) {
      tryHit(p, atk, others);
    }
    if (p.attack.t >= atk.startup + atk.active + atk.recover) p.attack = null;
  }

  const canAct = !inHitstun && !p.attack;
  const jumpEdge = inp.jump && !p.prevJump;
  const jabEdge = inp.jab && !p.prevJab;
  const smashEdge = inp.smash && !p.prevSmash;
  const downEdge = inp.down && !p.prevDown;
  p.prevJump = inp.jump; p.prevJab = inp.jab; p.prevSmash = inp.smash; p.prevDown = inp.down;

  const dir = (inp.right ? 1 : 0) - (inp.left ? 1 : 0);

  // --- Horizontal movement ---
  if (inHitstun) {
    // drift only from knockback; mild air resistance
    p.vx -= Math.sign(p.vx) * Math.min(Math.abs(p.vx), PHYS.HITSTUN_FRICTION * dt);
  } else if (p.grounded) {
    if (canAct && dir !== 0) {
      p.face = dir;
      const target = dir * chr.speed;
      const accel = 6500 * dt;
      p.vx += Math.max(-accel, Math.min(accel, target - p.vx));
    } else {
      p.vx -= Math.sign(p.vx) * Math.min(Math.abs(p.vx), PHYS.FRICTION * dt);
    }
  } else {
    // air control (allowed even mid-attack for drift)
    if (!inHitstun && dir !== 0) {
      if (canAct) p.face = dir;
      const next = p.vx + dir * chr.airAccel * dt;
      if (Math.abs(next) <= chr.airSpeed || Math.abs(next) < Math.abs(p.vx)) p.vx = next;
    }
  }

  // --- Jumping ---
  if (canAct && jumpEdge) {
    if (p.grounded) {
      p.vy = -chr.jumpVel;
      p.grounded = false;
      p.jumpsLeft = chr.jumps - 1;
    } else if (p.jumpsLeft > 0) {
      p.vy = -chr.jumpVel * 0.92;
      p.vx = dir !== 0 ? Math.max(-chr.airSpeed, Math.min(chr.airSpeed, p.vx)) : p.vx;
      p.jumpsLeft--;
      broadcast({ type: 'event', kind: 'djump', id: p.id, x: Math.round(p.x), y: Math.round(p.y) });
    }
  }

  // --- Drop through thin platforms ---
  if (p.grounded && downEdge && canAct) {
    const plat = map.platforms.find(pl =>
      !pl.main && Math.abs(p.y - pl.y) < 4 && p.x > pl.x - 10 && p.x < pl.x + pl.w + 10);
    if (plat) { p.y += 6; p.grounded = false; p.jumpsLeft = chr.jumps - 1; }
  }

  // --- Attacks ---
  if (canAct && (jabEdge || smashEdge)) {
    const key = smashEdge ? 'smash' : 'jab';
    if (dir !== 0) p.face = dir;
    p.attack = { key, t: 0, hitSet: new Set() };
    broadcast({ type: 'event', kind: 'swing', id: p.id, atk: key });
  }

  // --- Gravity & integration ---
  if (!p.grounded) {
    const ff = (inp.down && p.vy > 0 && !inHitstun) ? PHYS.FASTFALL : 1;
    p.vy = Math.min(PHYS.MAX_FALL, p.vy + PHYS.GRAV * ff * dt);
  }
  const prevY = p.y;
  p.x += p.vx * dt;
  p.y += p.vy * dt;

  // --- Platform collision (one-way, from above) ---
  let landed = false;
  if (p.vy >= 0) {
    for (const pl of map.platforms) {
      const top = pl.y;
      if (prevY <= top + 0.01 && p.y >= top &&
          p.x > pl.x - PHYS.BODY_W * 0.3 && p.x < pl.x + pl.w + PHYS.BODY_W * 0.3) {
        if (!pl.main && inp.down && p.vy > 600) continue; // fastfall through thin platforms
        p.y = top; p.vy = 0;
        landed = true;
        if (!p.grounded) {
          p.grounded = true;
          p.jumpsLeft = chr.jumps - 1;
          if (p.hitstunT > 0.25) p.hitstunT = 0.25; // landing reduces hitstun
        }
        break;
      }
    }
  }
  if (!landed && p.grounded) {
    // walked off an edge?
    const still = map.platforms.some(pl =>
      Math.abs(p.y - pl.y) < 2 && p.x > pl.x - PHYS.BODY_W * 0.3 && p.x < pl.x + pl.w + PHYS.BODY_W * 0.3);
    if (!still) { p.grounded = false; p.jumpsLeft = chr.jumps - 1; }
  }

  // --- Blast zones ---
  const b = map.blast;
  if (p.x < b.left || p.x > b.right || p.y > b.bottom || (p.y < b.top && inHitstun)) {
    koPlayer(p, map);
    return;
  }

  // --- Animation state ---
  let anim;
  if (inHitstun) anim = 'hit';
  else if (p.attack) anim = p.attack.key;
  else if (!p.grounded) anim = p.vy < -60 ? 'jump' : 'fall';
  else if (Math.abs(p.vx) > 50 && dir !== 0) anim = 'run';
  else anim = 'idle';
  if (anim !== p.anim) { p.anim = anim; p.animT = 0; }
  else p.animT += dt;
}

function battleTick(dt) {
  const map = MAPS[game.map];
  const parts = participants();
  if (now() < game.countdownEnd) return; // frozen during countdown

  for (const p of parts) simPlayer(p, dt, map, parts);
}

function snapshot() {
  return {
    type: 'snap',
    t: now(),
    countdown: Math.max(0, game.countdownEnd - now()),
    players: participants().map(p => ({
      id: p.id, char: p.char, name: p.name,
      x: Math.round(p.x * 10) / 10, y: Math.round(p.y * 10) / 10,
      vx: Math.round(p.vx), vy: Math.round(p.vy),
      face: p.face, anim: p.anim, animT: Math.round(p.animT * 1000) / 1000,
      dmg: Math.round(p.dmg), stocks: p.stocks,
      alive: p.alive ? 1 : 0, dead: p.deadT > 0 ? 1 : 0,
      inv: p.invulnT > 0 ? 1 : 0, grounded: p.grounded ? 1 : 0
    }))
  };
}

// ---------------------------------------------------------------------------
// Main loop
// ---------------------------------------------------------------------------

setInterval(() => {
  game.tick++;
  if (game.phase === 'battle') {
    battleTick(PHYS.TICK);
    if (game.phase === 'battle' && game.tick % 2 === 0) broadcast(snapshot());
  } else if (game.phase === 'victory') {
    if (now() - game.victoryAt > 6) toCharSelect();
  }
}, 1000 / 60);

// ---------------------------------------------------------------------------
// Connections
// ---------------------------------------------------------------------------

wss.on('connection', (ws) => {
  const id = nextId++;
  let player = null;

  ws.on('message', (raw) => {
    let msg;
    try { msg = JSON.parse(raw); } catch { return; }

    if (msg.type === 'join' && !player) {
      const name = String(msg.name || 'Fighter').slice(0, 14).trim() || 'Fighter';
      player = {
        id, ws, name,
        host: game.players.size === 0,
        ready: false, char: null, vote: null,
        spectating: game.phase === 'battle' || game.phase === 'victory' || game.phase === 'mapselect',
        alive: false, input: {}
      };
      game.players.set(id, player);
      ws.send(JSON.stringify({ type: 'welcome', id, phase: game.phase, map: game.map }));
      if (game.phase === 'battle') {
        ws.send(JSON.stringify({ type: 'battleStart', map: game.map, countdownEnd: game.countdownEnd }));
      }
      syncState();
      return;
    }
    if (!player) return;

    switch (msg.type) {
      case 'startSelect':
        if (player.host && game.phase === 'lobby' && game.players.size >= 1) toCharSelect();
        break;

      case 'pickChar':
        if (game.phase === 'charselect' && CHARACTERS[msg.char] && !player.spectating) {
          player.char = msg.char;
          player.ready = false;
          syncState();
        }
        break;

      case 'ready':
        if (game.phase === 'charselect' && player.char && !player.spectating) {
          player.ready = !!msg.ready;
          syncState();
          const parts = participants();
          if (parts.length >= 1 && parts.every(p => p.ready && p.char)) toMapSelect();
        }
        break;

      case 'voteMap':
        if (game.phase === 'mapselect' && MAPS[msg.map] && !player.spectating) {
          player.vote = msg.map;
          syncState();
          const parts = participants();
          if (parts.every(p => p.vote)) toBattle();
        }
        break;

      case 'input':
        if (game.phase === 'battle' && !player.spectating && player.alive) {
          const i = player.input;
          i.left = msg.left ? 1 : 0; i.right = msg.right ? 1 : 0;
          i.up = msg.up ? 1 : 0; i.down = msg.down ? 1 : 0;
          i.jump = msg.jump ? 1 : 0; i.jab = msg.jab ? 1 : 0; i.smash = msg.smash ? 1 : 0;
        }
        break;
    }
  });

  ws.on('close', () => {
    if (!player) return;
    game.players.delete(id);
    promoteHost();
    if (game.phase === 'battle') checkBattleEnd();
    if (game.players.size === 0) {
      game.phase = 'lobby';
      game.winnerId = null;
    }
    syncState();
  });
});

// ---------------------------------------------------------------------------

server.listen(PORT, () => {
  console.log('');
  console.log('  ============================================');
  console.log('   SMASH ARENA server running!');
  console.log('  ============================================');
  console.log(`   Local:    http://localhost:${PORT}`);
  const nets = os.networkInterfaces();
  for (const name of Object.keys(nets)) {
    for (const net of nets[name]) {
      if (net.family === 'IPv4' && !net.internal) {
        console.log(`   Network:  http://${net.address}:${PORT}   (friends on your wifi)`);
      }
    }
  }
  console.log('');
  console.log('   For friends over the internet, run a tunnel, e.g.:');
  console.log(`     npx localtunnel --port ${PORT}`);
  console.log('   and share the URL it prints.');
  console.log('');
});
